#include <bits/stdc++.h>
using namespace std;

void readInt(int &x) {
    char ch;
    x = 0; bool neg = false;
    do {
        ch = getchar();
        if (ch == '-') neg = true;
    } while (!isdigit(ch));
    while (isdigit(ch)) {
        x = x * 10 + (ch - '0');
        ch = getchar();
    }
    if (neg) x = -x;
}

void readLongLong(long long &x) {
    char ch;
    x = 0; bool neg = false;
    do {
        ch = getchar();
        if (ch == '-') neg = true;
    } while (!isdigit(ch));
    while (isdigit(ch)) {
        x = x * 10 + (ch - '0');
        ch = getchar();
    }
    if (neg) x = -x;
}

long long n, k, mod;
int jc[262155], inv[262155], jc2[262155], Log[262155];
int dp[262155][31];
bool vis[262155][31];
vector<pair<int, int>> tp;

int getcnt(int x) {
    int cnt = 0;
    while (x && (x & 1) == 0) {
        ++cnt; x >>= 1;
    }
    return cnt;
}

int ksm(int x, long long y) {
    int ret = 1;
    while (y) {
        if (y & 1) ret = (long long)ret * x % mod;
        x = (long long) x * x % mod; y >>= 1;
    }
    return ret;
}

int C(int n, int m) {
    return (long long)jc[n] * inv[m] % mod * inv[n - m] % mod;
}

int dfs(int n, int k) {
    if (n == 0) return 1;
    if (k == 0) return 0;
    if (dp[n][k] != -1) return dp[n][k];
    int ret = 0;
    int di = (1 << Log[n]);
    for (int i = n; i >= di; i -= 2) {
        ret = (ret + (long long)C(n, i) * dfs(n - i, k - 1) % mod * k) % mod;
    }
    return dp[n][k] = ret;
}

int bfs(int n, int k) {
    static queue<pair<int, int>> q;
    q.push({n, k});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        tp.emplace_back(x, y);
        if (x == 0 || y == 0) continue;
        int di = (1 << Log[x]);
        for (int i = x; i >= di; i -= 2) {
            if (jc2[i] + jc2[x - i] == jc2[x] && !vis[x - i][y - 1]) {
                vis[x - i][y - 1] = true;
                q.push({x - i, y - 1});
            }
        }
    }
    for (int i = (int)tp.size() - 1; i >= 0; --i) {
        int x = tp[i].first, y = tp[i].second;
        if (x == 0) {
            dp[x][y] = 1; continue;
        }
        if (y == 0) {
            dp[x][y] = 0; continue;
        }
        int di = (1 << Log[x]);
        for (int i = x; i >= di; i -= 2) {
            if (jc2[i] + jc2[x - i] == jc2[x])
                dp[x][y] = (dp[x][y] + (long long)C(x, i) * dp[x - i][y - 1] % mod * y) % mod;
        }
    }
    return dp[n][k];
}

int main() {
    readInt(n); readInt(k); readInt(mod);
    jc[0] = 1;
    memset(vis, 0, sizeof(vis));
    Log[0] = -1;
    for (int i = 1; i <= 262150; ++i) {
        jc[i] = (long long)jc[i - 1] * i % mod;
        Log[i] = Log[i >> 1] + 1;
        jc2[i] = jc2[i - 1] + getcnt(i);
    }
    inv[262150] = ksm(jc[262150], mod - 2);
    for (int i = 262149; i > 0; --i)
        inv[i] = (long long)inv[i + 1] * (i + 1) % mod;
    inv[0] = inv[1];
    if (n & 1) {
        printf("%d\n", ksm(k, n));
    } else {
        int cnt = 0;
        for (int i = 0; i < 62; ++i) {
            if (n & (1LL << i)) ++cnt;
        }
        int ans = ksm(k, n);
        printf("%d\n", ((ans - bfs(n, k)) % mod + mod) % mod);
    }
}
